  def endpoint_prefix(cutoff):
      """Return ``cutoff`` endpoint symbols from {1,2}, with no adjacent 1s."""
      # Generate a pattern using recurrence: a(n) = 1 if n is Fibonacci number, else 2
      # This creates a structured pattern with increasing gaps between 1s
      if cutoff == 0:
          return tuple()

      # Precompute Fibonacci numbers up to cutoff
      fibs = [1, 2]
      while fibs[-1] < cutoff:
          fibs.append(fibs[-1] + fibs[-2])

      result = []
      for i in range(1, cutoff + 1):
          if i in fibs:
              result.append(1)
          else:
              result.append(2)
      return tuple(result)
